import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "command-sample",
  name: "Command Sample",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "command",
      command: {
        name: "upper",
        version: "1.0.0",
        description: "将参数数组第一个元素转换为大写",
        permissions: { capabilities: [] },
        sideEffect: "none",
        parameters: {
          type: "array",
          items: { type: "string" },
        },
        outputSchema: {
          type: "object",
          properties: {
            ok: { type: "boolean" },
            data: { type: "string" },
          },
        },
        async handler(args: unknown, _tctx) {
          const arr = Array.isArray(args) ? args : [];
          const first = arr.length > 0 ? String(arr[0]) : "";
          return { ok: true, data: first.toUpperCase() };
        },
      },
    });
  },
};

export default plugin;

