import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "command-probe",
  name: "Command Probe",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "tool",
      tool: {
        name: "probe_command_entry",
        version: "1.0.0",
        description: "通过 tctx.invoke 探测并调用宿主命令入口 ready",
        permissions: { capabilities: [] },
        sideEffect: "none",
        parameters: { type: "object", properties: {} },
        outputSchema: { type: "object" },
        async handler(_args: unknown, tctx) {
          const attempts: any[] = [];
          const shapes: Array<[string, any]> = [
            ["command:ready", { kind: "command", name: "ready", args: [] }],
            ["ready", { name: "ready", args: [] }],
            ["command/ready", { command: "ready", args: [] }],
          ];
          for (const [label, payload] of shapes) {
            try {
              const r = await (tctx as any).invoke(label, payload);
              attempts.push({ label, ok: true, result: r });
            } catch (e: any) {
              attempts.push({ label, ok: false, error: String(e?.message ?? e) });
            }
          }
          return { ok: true, data: attempts };
        },
      },
    });
  },
};

export default plugin;

